type Point = struct {
    int x;
    int y;
} with {

    constructor(int x, int y) {
        self.x = x;
        self.y = y;
    }

    mtd int • sum() {
        return self.x + self.y;
    }

    mtd int <- product() {
        return self.x * self.y;
    }

    mtd is_origin() : bool {
        return self.x == 0 && self.y == 0;
    }
}
pub fnc main(): int {
    let p = Point(10, 20);
    print(p.sum());
    print(p.product());
    print(p.is_origin());
    return 0;
}

